/* ===== Buttons Css ===== */
.pricing-style-one .primary-btn {
  background: var(--primary);
  color: var(--white);
  box-shadow: var(--shadow-2);
}
.pricing-style-one .active.primary-btn, .pricing-style-one .primary-btn:hover, .pricing-style-one .primary-btn:focus {
  background: var(--primary-dark);
  color: var(--white);
  box-shadow: var(--shadow-4);
}
.pricing-style-one .deactive.primary-btn {
  background: var(--gray-4);
  color: var(--dark-3);
  pointer-events: none;
}

/*===== PRICING STYLE ONE =====*/
.pricing-one {
  padding: 100px 0;
}

.pricing-style-one {
  box-shadow: var(--shadow-4);
  padding: 45px 30px;
  border-radius: 8px;
  position: relative;
  z-index: 1;
  overflow: hidden;
  background-color: var(--white);
  margin-top: 50px;
}
@media only screen and (min-width: 768px) and (max-width: 991px), (max-width: 767px) {
  .pricing-style-one {
    padding: 35px 30px;
  }
}
.pricing-style-one .sub-title {
  font-size: 16px;
  color: var(--black);
  position: relative;
  padding: 6px 20px;
  display: inline-block;
  border: 2px solid var(--primary);
  border-radius: 30px;
}
.pricing-style-one .price {
  display: block;
  font-size: 55px;
  font-weight: 600;
  line-height: 80px;
  margin-top: 25px;
  color: var(--black);
}
@media (max-width: 767px) {
  .pricing-style-one .price {
    font-size: 45px;
    margin-top: 16px;
  }
}
@media only screen and (min-width: 576px) and (max-width: 767px) {
  .pricing-style-one .price {
    font-size: 50px;
    margin-top: 20px;
  }
}
.pricing-style-one .year {
  color: var(--dark-3);
  margin-top: 3px;
}
.pricing-style-one .pricing-list {
  margin-top: 40px;
}
.pricing-style-one .pricing-list li {
  color: var(--dark-3);
  margin-top: 16px;
}
.pricing-style-one .pricing-list li i {
  color: var(--primary);
  margin-right: 8px;
}
.pricing-style-one .pricing-btn {
  margin-top: 42px;
}
.pricing-style-one .bottom-shape {
  position: absolute;
  bottom: -20px;
  left: 0;
  width: 101%;
  z-index: -1;
}

/*===== PRICING STYLE 2 =====*/
.primary-btn { background: var(--secondary); color: var(--white); box-shadow: var(--shadow-2); padding: 12px 26px; border-radius: 6px; font-weight: 600; border: none; }
.primary-btn:hover { background: var(--secondary-dark); color: var(--white); box-shadow: var(--shadow-4); }
.outline-btn { border: 1.5px solid var(--secondary); color: var(--secondary); padding: 11px 24px; border-radius: 6px; font-weight: 600; background: transparent; }
.outline-btn:hover { background: var(--secondary); color: var(--white); }
.pricing-tables-style-3 { background: var(--light-2); padding: 70px 0; }
.pricing-tables-style-3 .price-box { position: relative; background: var(--white); border: 1px solid var(--gray-4); border-radius: 14px; padding: 36px 28px; box-shadow: var(--shadow-2); height: 100%; }
.pricing-tables-style-3 .price-box.featured { border: 2px solid var(--secondary); box-shadow: var(--shadow-5); }
.pricing-tables-style-3 .popular-tag { position: absolute; top: 16px; right: 16px; background: var(--secondary); color: #fff; font-size: 12px; font-weight: 600; padding: 4px 12px; border-radius: 20px; }
.pricing-tables-style-3 h2, .pricing-tables-style-3 h6 { color: var(--black); }
.pricing-tables-style-3 p, .pricing-tables-style-3 li { color: var(--dark-2); margin-bottom: 10px; }
